use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

pub fn IS_ZEROIZED(response: Common::Response_Impl) -> bool
{
  MATRICS_Model_Transformations::IS_NULL_REQUEST(response.request) &
    (response.validLogCount == 0u32) &
    (response.moreAvailable == false) &
    (response.nextStartTime == 0u64) &
    (0..=response.logs.len() - 1).all(|response_log_index| MATRICS_Model_Transformations::IS_NULL_LOG(response.logs[response_log_index]))
}

/** Initialize EntryPointContract
  *
  * guarantee defaultZeroize
  * @param zeroize_cmd post-state state variable
  */
pub fn initialize_defaultZeroize(zeroize_cmd: bool) -> bool
{
  zeroize_cmd == false
}

/** IEP-Guar: Initialize Entrypoint for dataManager
  *
  * @param zeroize_cmd post-state state variable
  * @param api_encrypted_log outgoing event data port
  * @param api_response_log outgoing event data port
  * @param api_storage_request outgoing event data port
  */
pub fn initialize_IEP_Guar(
  zeroize_cmd: bool,
  api_encrypted_log: Option<Common::StoredLogFile_Impl>,
  api_response_log: Option<Common::AnalysisResponse_Impl>,
  api_storage_request: Option<Common::AnalysisRequest_Impl>) -> bool
{
  initialize_defaultZeroize(zeroize_cmd)
}

