/** Compute Entrypoint Contract
  *
  * guarantee zeroize_cmd_variable
  *   G: Once a zeroize command is seen, always zeroize.
  * @param In_zeroize_cmd pre-state state variable
  * @param zeroize_cmd post-state state variable
  * @param api_zeroize incoming event port
  */
pub fn compute_spec_zeroize_cmd_variable_guarantee(
  In_zeroize_cmd: bool,
  zeroize_cmd: bool,
  api_zeroize: Option<u8>) -> bool
{
  zeroize_cmd == (api_zeroize.is_some() || In_zeroize_cmd)
}

/** Compute Entrypoint Contract
  *
  * guarantee Zeroize_Payload
  *   G: Zeroize outgoing responses once an alert is received and when a request has been made.
  * @param zeroize_cmd post-state state variable
  * @param api_request_log incoming event data port
  * @param api_response_log outgoing event data port
  */
pub fn compute_spec_Zeroize_Payload_guarantee(
  zeroize_cmd: bool,
  api_request_log: Option<Common::AnalysisRequest_Impl>,
  api_response_log: Option<Common::AnalysisResponse_Impl>) -> bool
{
  implies!(
    zeroize_cmd & api_request_log.is_some(),
    IS_ZEROIZED(api_response_log.unwrap().payload))
}

/** CEP-T-Guar: Top-level guarantee contracts for dataManager's compute entrypoint
  *
  * @param In_zeroize_cmd pre-state state variable
  * @param zeroize_cmd post-state state variable
  * @param api_zeroize incoming event port
  * @param api_request_log incoming event data port
  * @param api_response_log outgoing event data port
  */
pub fn compute_CEP_T_Guar(
  In_zeroize_cmd: bool,
  zeroize_cmd: bool,
  api_zeroize: Option<u8>,
  api_request_log: Option<Common::AnalysisRequest_Impl>,
  api_response_log: Option<Common::AnalysisResponse_Impl>) -> bool
{
  let r0: bool = compute_spec_zeroize_cmd_variable_guarantee(In_zeroize_cmd, zeroize_cmd, api_zeroize);
  let r1: bool = compute_spec_Zeroize_Payload_guarantee(zeroize_cmd, api_request_log, api_response_log);

  return r0 && r1;
}

/** CEP-Post: Compute Entrypoint Post-Condition for dataManager
  *
  * @param In_zeroize_cmd pre-state state variable
  * @param zeroize_cmd post-state state variable
  * @param api_zeroize incoming event port
  * @param api_HMD_log incoming event data port
  * @param api_encrypted_response incoming event data port
  * @param api_request_log incoming event data port
  * @param api_encrypted_log outgoing event data port
  * @param api_response_log outgoing event data port
  * @param api_storage_request outgoing event data port
  */
pub fn compute_CEP_Post(
  In_zeroize_cmd: bool,
  zeroize_cmd: bool,
  api_zeroize: Option<u8>,
  api_HMD_log: Option<Common::Log_Impl>,
  api_encrypted_response: Option<Common::EncryptedAnalysisResponse_Impl>,
  api_request_log: Option<Common::AnalysisRequest_Impl>,
  api_encrypted_log: Option<Common::StoredLogFile_Impl>,
  api_response_log: Option<Common::AnalysisResponse_Impl>,
  api_storage_request: Option<Common::AnalysisRequest_Impl>) -> bool
{
  // CEP-Guar: guarantee clauses of dataManager's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(In_zeroize_cmd, zeroize_cmd, api_zeroize, api_request_log, api_response_log);

  return r0;
}
